import React, { useState } from 'react';
import { apiDangNhap } from '../api/goi_api';

const DangNhap = () => {
    const [form, setForm] = useState({ ten: '', mk: '' });

    const handleLogin = async (e) => {
        e.preventDefault();
        try {
            const res = await apiDangNhap({ ten_dang_nhap: form.ten, mat_khau: form.mk });
            alert("Đăng nhập thành công!");
        } catch (error) {
            alert("Lỗi kết nối server");
        }
    };

    return (
        <div style={styles.container}>
            <div style={styles.loginBox}>
                {/* Bên trái: Banner tối */}
                <div style={styles.leftSide}>
                    <div style={styles.logoContainer}>
                        <span style={styles.icon}>🛡️</span>
                        <h1 style={styles.brandName}>A&RMS</h1>
                    </div>
                    <div style={styles.welcomeText}>
                        <p style={styles.mainWelcome}>Chào mừng đã đến với A&RMS,</p>
                        <p style={styles.subWelcome}>Phần mềm quản lý căn hộ và khu dân cư!</p>
                    </div>
                </div>

                {/* Bên phải: Form */}
                <div style={styles.rightSide}>
                    <h2 style={styles.title}>Apartment & Resident Management System</h2>
                    <form onSubmit={handleLogin} style={styles.form}>
                        <input 
                            type="text" 
                            placeholder="Tài khoản ..." 
                            style={styles.input}
                            onChange={(e) => setForm({...form, ten: e.target.value})}
                        />
                        <input 
                            type="password" 
                            placeholder="Mật khẩu ..." 
                            style={styles.input}
                            onChange={(e) => setForm({...form, mk: e.target.value})}
                        />
                        <button type="submit" style={styles.loginBtn}>Đăng nhập</button>
                    </form>
                    <a href="#" style={styles.registerLink}>Đăng ký tài khoản mới</a>
                </div>
            </div>
        </div>
    );
};

const styles = {
    container: {
        height: '100vh',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        backgroundColor: '#f4f7f6', // Màu nền nhạt sang trọng
        fontFamily: "'Inter', 'Segoe UI', sans-serif",
    },
    loginBox: {
        display: 'flex',
        width: '900px',
        height: '500px',
        backgroundColor: '#fff',
        borderRadius: '20px', // Bo góc sâu như ảnh mẫu
        boxShadow: '0 20px 40px rgba(0,0,0,0.1)', // Đổ bóng mềm
        overflow: 'hidden',
    },
    leftSide: {
        flex: 1,
        backgroundColor: '#222', // Màu đen xám của ảnh mẫu
        padding: '50px',
        color: '#fff',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center',
    },
    logoContainer: {
        display: 'flex',
        alignItems: 'center',
        gap: '15px',
        marginBottom: '40px',
    },
    icon: { fontSize: '32px' },
    brandName: { fontSize: '30px', fontWeight: 'bold', letterSpacing: '2px', margin: 0 },
    welcomeText: { lineHeight: '1.5' },
    mainWelcome: { fontSize: '18px', fontWeight: '600', marginBottom: '5px' },
    subWelcome: { fontSize: '14px', opacity: 0.7 },

    rightSide: {
        flex: 1.2,
        padding: '60px',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center',
    },
    title: {
        fontSize: '18px',
        color: '#666',
        textAlign: 'center',
        marginBottom: '35px',
        fontWeight: '400',
    },
    form: { display: 'flex', flexDirection: 'column', gap: '20px' },
    input: {
        padding: '14px 18px',
        borderRadius: '8px',
        border: '1px solid #eee',
        backgroundColor: '#fafafa',
        fontSize: '14px',
        outline: 'none',
        transition: '0.3s',
    },
    loginBtn: {
        padding: '14px',
        backgroundColor: '#4e342e', // Màu nâu gỗ đặc trưng
        color: '#fff',
        border: 'none',
        borderRadius: '8px',
        fontSize: '16px',
        fontWeight: '600',
        cursor: 'pointer',
        marginTop: '10px',
    },
    registerLink: {
        textAlign: 'center',
        marginTop: '25px',
        color: '#2e7d32', // Màu xanh lá giống ảnh
        fontSize: '13px',
        textDecoration: 'none',
        fontWeight: '500',
    }
};

export default DangNhap;
